#!/usr/bin/env python3
"""Package the committed PMRE runtime for an ordinary file:// browser; no venue runtime dependencies."""
import argparse,hashlib,json,pathlib,subprocess,zipfile,datetime
p=argparse.ArgumentParser();p.add_argument('--out',required=True);p.add_argument('--name',default='pmre2026-architect-to-xr-chitect-offline-deck-v8-review-2026-11-18.zip');a=p.parse_args()
r=pathlib.Path(__file__).resolve().parent.parent;out=pathlib.Path(a.out).resolve();out.mkdir(parents=True,exist_ok=True);dest=out/a.name
if dest.exists():raise SystemExit(f'Preserving existing archive; choose a new --name: {dest}')
tracked=subprocess.check_output(['git','ls-files','-z'],cwd=r).decode().split('\0');dirs=('assets/','slides/','media/','talk/','styles/','resources/')
files=sorted(f for f in tracked if f and (f=='index.html' or f.startswith(dirs)) and pathlib.Path(f).name!='.DS_Store' and not f.endswith('.gitignore'))
if len(files)<30:raise SystemExit('Incomplete project package: fewer than 30 files')
commit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=r,text=True).strip();entries=[dict(path=f,bytes=(r/f).stat().st_size,sha256=hashlib.sha256((r/f).read_bytes()).hexdigest()) for f in files]
manifest=dict(display_name='Architect to XR-chitect — PMRE 2026 offline presentation, v8 review',purpose='Present the complete local deck on a Windows PC with only Chrome or Firefox.',project='PMRE 2026',subject='Architect to XR-chitect',status='review build; presenter and venue acceptance pending',created_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),source_repository='https://github.com/ibrews/pmre-2026-xr-chitect',source_commit=commit,source_branch='story/v8',source_path=str(r),creation_tool='python3 tools/package_offline.py',included='All committed runtime HTML, classic scripts, frames, fonts, styles and media; starter guide/resources page.',omitted='Git metadata, source tooling, promo assets and QA screenshots. No cloud upload.',open_instructions='Extract ALL files to a local folder. Double-click index.html and choose Chrome or Firefox. Never open index.html inside the ZIP. Press F11 for full screen; arrows advance, O selects cuts, Shift+N opens notes.',offline_strategy='No runtime fetch of JSON, no module imports over file://. Classic script tags and relative HTML frames. Local fonts and relative video src. Camera concept uses its built-in 2D projection over file://. External resources links need internet only when clicked.',acceptance_evidence='See KB receipt and adjacent qa-file report; packaging alone is not a Windows hardware test.',known_limitations=['PMRE20 offer and booking terms: https://alexcoulombepresents.com/pmre.','Browser security governs notes-popup storage and fullscreen.','Tested file:// in macOS headless Chrome and Firefox; physical Windows/venue hardware not tested.'],payload_file_count=len(files),payload_byte_count=sum(x['bytes'] for x in entries),whole_archive_checksum='SHA-256 in adjacent .sha256 sidecar; external to avoid self-referential hash.',files=entries)
launch='''PMRE 2026 — ARCHITECT TO XR-CHITECT\nAlex Coulombe Presents · v8 review build\n\nWINDOWS: right-click the ZIP > Extract All. Keep the folders together.\nDouble-click index.html. Choose Google Chrome or Firefox if asked.\nNo Python, server, install, or internet is needed to present the deck.\nDo not open index.html from inside Windows ZIP preview.\n\nPress F11 for full screen. Right/left arrows navigate. Some slides have\nclick-controlled reveals. O opens talk options; Shift+N opens notes.\nDefault is the full story. Shorter cuts are available in O.\nAll presentation videos play silently and loop.\nThe QR and external resources links need internet on the viewer's device;\nthe resources page and second-brain starter kit are included locally too.\n\nKeep this review build until Alex approves a successor.\n'''
with zipfile.ZipFile(dest,'w',compression=zipfile.ZIP_DEFLATED,compresslevel=3) as z:
 for f in files:z.write(r/f,f)
 z.writestr('START-HERE.txt',launch);z.writestr('archive-manifest.json',json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
h=hashlib.sha256(dest.read_bytes()).hexdigest();dest.with_suffix('.zip.sha256').write_text(f'{h}  {dest.name}\n');print(json.dumps(dict(zip=str(dest),bytes=dest.stat().st_size,sha256=h,payload_files=len(files),source_commit=commit),indent=2))
